'use strict';
const categoryLabel=c=>c==='beginner'?L('Beginner books','Buku pemula','入门绘本'):L('Standard books','Buku standar','标准绘本');
const savedBook=id=>id===p().book?p():(p().books?.[id+':standard']||{scene:0,done:[]});
function collectionsView(){return `<section id="books" class="collection-picker"><div class="section-head"><div><span class="eyebrow">${L('TWO COLLECTIONS • DIFFERENT BOOKS','DUA KOLEKSI • BUKU BERBEDA','两个书架，不同的书')}</span><h2>${L('Find your next book','Temukan buku berikutnya','找到下一本书')}</h2></div></div><div class="collection-doors">${['beginner','standard'].map(c=>`<a href="#${c}" class="collection-door ${c}"><img src="${c==='beginner'?BOOKS.colors.cover:BOOKS.pet.cover}" alt="" loading="lazy"><div><span class="collection-symbol">${c==='beginner'?'🌱':'🌳'}</span><h3>${categoryLabel(c)}</h3><p>${c==='beginner'?L('First words, colors, and playful repetition. Short books made for starting out.','Kata pertama, warna, dan pengulangan seru. Buku pendek untuk memulai.','启蒙词汇、颜色和有趣的重复。专为起步设计的短绘本。'):L('Characters, adventures, and everyday choices. Longer stories to explore together.','Tokoh, petualangan, dan pilihan sehari-hari. Cerita lebih panjang untuk dijelajahi bersama.','人物、冒险和日常选择。一起探索更长的故事。')}</p><strong>${L('Explore this collection','Jelajahi koleksi ini','探索这个书架')} →</strong></div></a>`).join('')}</div><p class="note">${L('Each collection has its own titles. Both offer translation and the same five audio levels.','Setiap koleksi memiliki judul sendiri. Keduanya menyediakan terjemahan dan lima tingkat audio.','每个书架都有独立的书目，都支持翻译和五档语音。')}</p></section>`;}
function collectionPage(){const category=route==='beginner'?'beginner':'standard';return `<a class="quiet-link" href="#home">← ${L('All collections','Semua koleksi','所有书架')}</a><div class="collection-heading"><span class="collection-symbol">${category==='beginner'?'🌱':'🌳'}</span><div><span class="eyebrow">${L('YOUR BOOKSHELF','RAK BUKUMU','你的书架')}</span><h1>${categoryLabel(category)}</h1><p>${category==='beginner'?L('Small books for first words and discoveries.','Buku kecil untuk kata dan penemuan pertama.','用小绘本认识词汇，发现世界。'):L('Spend time with Ping’s world, one illustrated page at a time.','Jelajahi dunia Ping, satu halaman bergambar setiap kali.','一页一页，走进平平的绘本世界。')}</p></div></div><div class="book-shelf">${Object.entries(BOOKS).filter(([,b])=>b.category===category).map(([id,b])=>{const pr=savedBook(id),count=b.images.length,done=pr.done.length;return `<article class="book-tile"><a href="#read?book=${id}"><div class="cover-wrap"><img src="${b.cover}" alt="${e(b.alt[id==='pet'?5:0])}"><span class="page-count">${count} ${L('pages','halaman','页')}</span></div><div class="book-info"><span class="eyebrow">${b.tag[langIndex()]}</span><h3>${b.title[langIndex()]}</h3><p>${b.desc[langIndex()]}</p><div class="book-progress"><span>${done}/${count} ${L('pages explored','halaman dijelajahi','页已探索')}</span><progress value="${done}" max="${count}"></progress></div><div class="book-footer"><span>${done||pr.scene?L('Continue reading','Lanjut membaca','继续阅读'):L('Open book','Buka buku','打开绘本')}</span><b>↗</b></div></div></a></article>`}).join('')}</div><div class="collection-switch"><a class="btn secondary" href="#${category==='beginner'?'standard':'beginner'}">${categoryLabel(category==='beginner'?'standard':'beginner')} →</a></div>`;}
const audioDescriptions=()=>[
L('One word','Satu kata','一个词'),L('Two words','Dua kata','两个词'),L('Three words','Tiga kata','三个词'),L('Short phrases','Frasa pendek','短语'),L('Full sentences','Kalimat utuh','完整句子')];
const audioExample='Ping and Popo play in the garden.';
learningChoices=function(){const labels=audioDescriptions(),chunks=C.readingChunks(audioExample,mode,phraseSegments);return `<section class="listening-studio" aria-label="${L('Listening controls','Kontrol mendengarkan','听读设置')}"><div class="studio-heading"><div><span class="eyebrow">${L('LISTEN AT YOUR PACE','DENGARKAN SESUAI RITMEMU','按自己的节奏听')}</span><h2>${L('How much at a time?','Seberapa banyak sekaligus?','一次听多少？')}</h2><p>${L('Choose a level. Ping pauses after each part so you can repeat.','Pilih tingkat. Ping berhenti setelah setiap bagian agar kamu bisa mengulang.','选择一档。平平在每个片段后停顿，让你跟读。')}</p></div><label for="translationChoice">${L('Help me understand in','Bantu aku memahami dalam','用以下语言帮助理解')}<select id="translationChoice"><option value="">${L('English only','Hanya bahasa Inggris','仅英语')}</option><option value="id" ${nativeLang()==='id'?'selected':''}>Bahasa Indonesia</option><option value="zh" ${nativeLang()==='zh'?'selected':''}>简体中文</option></select></label></div><div class="listening-levels" role="group" aria-label="${L('Five audio levels','Lima tingkat audio','五档语音')}">${labels.map((label,i)=>`<button data-action="mode" data-index="${i}" aria-pressed="${mode===i}" aria-label="${L('Level','Tingkat','档')} ${i+1}: ${label}" class="${mode===i?'selected':''}"><span class="level-top"><b>${i+1}</b><span aria-hidden="true">${i===mode?'✓':''}</span></span><strong>${label}</strong><span class="pace-bars" aria-hidden="true">${Array.from({length:5-i},()=>`<i style="flex:${i+1}"></i>`).join('')}</span></button>`).join('')}</div><div class="level-preview"><div><span class="preview-label">${L('LEVEL','TINGKAT','档')} ${mode+1} · ${labels[mode]}</span><div class="chunk-preview" lang="en">${chunks.map(x=>`<span>${e(x)}</span>`).join('<i aria-hidden="true">Ⅱ</i>')}</div><small>${L('Each gap is your turn to speak.','Setiap jeda adalah giliranmu berbicara.','每次停顿都轮到你开口。')}</small></div>${btn('▶ '+L('Try this level','Coba tingkat ini','试试这一档'),'tryLevel','secondary small')}</div></section>`;};
const baseReader=readView;
readView=function(){let html=baseReader();html=html.replace('href="#home" class="quiet-link"','href="#'+book().category+'" class="quiet-link"').replace(L('Story garden','Taman cerita','故事花园'),categoryLabel(book().category));html=html.replace('<div class="storybook">',`${readerToolbar()}<div class="storybook">`);return html;};
function readerToolbar(){return `<div class="book-toolbar"><label for="pageJump">${L('Go to page','Ke halaman','跳转页面')}<select id="pageJump">${STORY.map((_,i)=>`<option value="${i}" ${p().scene===i?'selected':''}>${i+1}. ${e(SCENE_TITLES[state.lang][i])}</option>`).join('')}</select></label><span class="bookmark-status">${L('Your place is saved automatically','Posisimu disimpan otomatis','自动保存阅读位置')}</span><div class="page-turners">${btn('←','prev','secondary small',`aria-label="Previous page" ${p().scene===0?'disabled':''}`)}<span>${p().scene+1} / ${STORY.length}</span>${btn('→','next','secondary small',`aria-label="Next page" ${p().scene===STORY.length-1?'disabled':''}`)}</div></div>`;}
const previousAction=action;
action=async function(el){if(el.dataset.action==='tryLevel'){return speak(audioExample)}const oldScene=p().scene;await previousAction(el);if(route==='read'&&['prev','next','scene'].includes(el.dataset.action)&&p().scene!==oldScene){document.querySelector('.book-toolbar')?.scrollIntoView({block:'start',behavior:'smooth'});}}
document.addEventListener('change',ev=>{if(ev.target.id==='pageJump'){stop();p().scene=Number(ev.target.value);save();render();history.replaceState(null,'','#read?book='+p().book+'&page='+(p().scene+1));document.querySelector('.book-toolbar')?.scrollIntoView({block:'start'});}});
document.addEventListener('keydown',ev=>{if(route!=='read'||$('#dialog').open||/INPUT|TEXTAREA|SELECT|BUTTON/.test(ev.target.tagName)||ev.target.isContentEditable||ev.altKey||ev.ctrlKey||ev.metaKey)return;const step=ev.key==='ArrowRight'?1:ev.key==='ArrowLeft'?-1:0;if(step&&p().scene+step>=0&&p().scene+step<STORY.length){ev.preventDefault();action({dataset:{action:step===1?'next':'prev'}});}});
// The color book has its own check feedback and age-appropriate output guidance.
const oldCheck=checkView;
checkView=function(){let html=oldCheck();if(p().book==='exercise')html=html.replace(L('Have another look at the story. Think about what care means.','Baca lagi ceritanya. Pikirkan arti kepedulian.','再看看故事，想想关心是什么意思。'),L('Look at page eight. What does Brenda help Ping make?','Lihat halaman delapan. Apa yang Brenda bantu Ping buat?','看看第八页。布伦达帮助平平制作了什么？'));if(p().book==='colors')html=html.replace(L('Have another look at the story. Think about what care means.','Baca lagi ceritanya. Pikirkan arti kepedulian.','再看看故事，想想关心是什么意思。'),L('Look at the firetruck on page one. What color do you see?','Lihat mobil pemadam di halaman pertama. Warna apa yang kamu lihat?','看看第一页的消防车。你看到了什么颜色？'));return html;};
const previousWrite=writeView;
writeView=function(){let html=previousWrite();if(book().category==='beginner')html=html.replace(t('effortFirst'),L('Point, say a word, or draw your answer with a grown-up. You can write a short English phrase when you are ready.','Tunjuk, ucapkan satu kata, atau gambar jawaban bersama orang dewasa. Tulis frasa pendek jika sudah siap.','和大人一起指一指、说一个词，或画出答案。准备好后，可以写一个简短的英语短语。'));return html;};
navigate();save();
